estilos.css:
.plans-shell {
  width:min(100%,980px);
  margin:0 auto;
  padding:26px 16px 42px;
  color:var(--text);
}
.plans-heading h1 { margin:0;color:var(--primary);font-size:26px;letter-spacing:-.03em; }
.plans-heading p { max-width:680px;margin:7px 0 0;color:var(--muted);font-size:13px;line-height:1.55; }

.current-summary {
  margin:18px 0;
  padding:12px 14px;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:12px;
  border:1px solid #ead7a8;
  border-radius:14px;
  background:#fffaf0;
}
.current-summary strong { display:block;color:#6d4d10;font-size:13px; }
.current-summary span { display:block;margin-top:3px;color:#806a3b;font-size:11px; }
.current-pill {
  flex:none!important;margin:0!important;padding:5px 10px;border-radius:999px;background:#fff1c7;
  color:#77510b!important;font-size:10px!important;font-weight:900;text-transform:uppercase;letter-spacing:.04em;
}

.plans-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px; }
.plan-card {
  min-width:0;display:flex;flex-direction:column;padding:18px;border:1px solid var(--line);
  border-radius:18px;background:#fff;box-shadow:0 3px 12px rgba(16,35,63,.04);
}
.plan-card.current { border:1.5px solid #d6b76e;background:#fffdf8;box-shadow:0 8px 22px rgba(184,137,50,.10); }
.plan-badge {
  align-self:flex-start;min-height:24px;display:inline-flex;align-items:center;padding:3px 9px;border-radius:999px;
  background:#f2f4f7;color:#475467;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.045em;
}
.current .plan-badge { background:#fff2c8;color:#7b560d; }
.plan-card h2 { margin:14px 0 4px;color:var(--primary);font-size:20px;letter-spacing:-.02em; }
.plan-description { min-height:38px;margin:0;color:var(--muted);font-size:12px;line-height:1.5; }
.price { margin:18px 0 0;color:var(--primary);font-size:27px;font-weight:900;letter-spacing:-.03em; }
.price small { color:var(--muted);font-size:11px;font-weight:700;letter-spacing:0; }

.course-access {
  margin:14px 0 0;padding:11px 12px;display:grid;grid-template-columns:34px minmax(0,1fr);gap:10px;align-items:center;
  border:1px solid #dbe3ee;border-radius:12px;background:#f8fafc;
}
.course-icon { width:34px;height:34px;display:grid;place-items:center;border-radius:9px;background:#e8eef6;color:var(--primary);font-size:12px;font-weight:900; }
.course-access strong { display:block;color:var(--primary);font-size:11px; }
.course-access span { display:block;margin-top:2px;color:var(--muted);font-size:10px;line-height:1.4; }
.course-none { background:#fafafa; }
.course-none .course-icon { background:#f2f4f7;color:#98a2b3; }

.features { display:grid;gap:9px;margin:16px 0 20px;padding-top:15px;border-top:1px solid #edf1f5; }
.feature { display:grid;grid-template-columns:18px minmax(0,1fr);gap:8px;align-items:start;color:#344054;font-size:12px;line-height:1.45; }
.feature b {
  width:18px;height:18px;display:grid;place-items:center;border-radius:50%;background:#e9f7ef;color:#08744e;font-size:11px;
}
.feature.muted { color:#98a2b3; }
.feature.muted b { background:#f2f4f7;color:#98a2b3; }
.plan-primary {
  width:100%;min-height:44px;margin-top:auto;padding:10px 14px;border:0;border-radius:11px;background:var(--primary);
  color:#fff;font-size:12px;font-weight:900;cursor:pointer;
}
.current-button { background:#7c5a18; }
.plan-secondary {
  width:100%;min-height:44px;margin-top:8px;padding:10px 14px;border:1px solid var(--line);border-radius:11px;
  background:#fff;color:var(--primary);font-size:12px;font-weight:900;cursor:pointer;
}
.renewal { margin-top:9px;color:var(--muted);font-size:10px;text-align:center; }
.commercial-note {
  margin-top:18px;padding:12px 14px;display:grid;gap:4px;border:1px solid var(--line);
  border-radius:13px;background:#f8fafc;color:var(--muted);font-size:10px;line-height:1.5;
}
.commercial-note strong { color:var(--primary);font-size:11px; }
.op-toast {
  position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:100;
  display:none;max-width:min(92vw,460px);padding:10px 14px;border-radius:10px;background:#172033;color:#fff;font-size:11px;
}
.op-toast.show { display:block; }

@media(max-width:700px) {
  .plans-grid { grid-template-columns:1fr; }
  .current-summary { align-items:flex-start;flex-direction:column; }
  .plans-shell { padding-left:13px;padding-right:13px; }
  .plan-description { min-height:0; }
}
